def find_diamonds(g):
    H,W=len(g),len(g[0]); cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    # diamonds radius1: group into connected components (touching via adjacency)
    comps=[]; seen=set()
    for cell in cells:
        if cell in seen: continue
        stack=[cell]; comp=set()
        while stack:
            x=stack.pop()
            if x in seen or x not in set(cells): continue
            seen.add(x); comp.add(x)
            r,c=x
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if (r+dr,c+dc) in set(cells) and (r+dr,c+dc) not in seen: stack.append((r+dr,c+dc))
        comps.append(sorted(comp))
    return [(sum(r for r,_ in comp)/len(comp), sum(c for _,c in comp)/len(comp)) for comp in comps]

def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    cents=find_diamonds(g)
    for i in range(len(cents)):
        for j in range(i+1,len(cents)):
            r1,c1=cents[i]; r2,c2=cents[j]
            if r1==r2:
                for c in range(int(min(c1,c2))+1,int(max(c1,c2))):
                    if g[int(r1)][c]==0: g[int(r1)][c]=1
            if c1==c2:
                for r in range(int(min(r1,r2))+1,int(max(r1,r2))):
                    if g[r][int(c1)]==0: g[r][int(c1)]=1
    return g
